nationality_urls = list(dict.fromkeys(
    h["url"] for hits in nationality_hits for h in hits
    if not h["url"].endswith(".pdf") and "nobelprize.org" not in h["url"]
))
nationality_pages = fetch_many(nationality_urls, focus="Explicit nationality or citizenship of Nobel Chemistry laureates.")
source_texts.update(dict(zip(nationality_urls, nationality_pages)))
nat_schema = {
    "type": "object",
    "properties": {"records": {
        "type": "array",
        "items": {
            "type": "object",
            "properties": {
                "laureate": {"type": "string"},
                "nationality": cell_schema
            },
            "required": ["laureate", "nationality"],
            "additionalProperties": False
        }
    }},
    "required": ["records"],
    "additionalProperties": False
}
nat_prompts = []
for y, hits in zip(years[1:], nationality_hits):
    evidence = [
        {"url": h["url"], "text": source_texts[h["url"]]}
        for h in hits if h["url"] in nationality_urls
    ]
    names = [r["cells"]["laureate"]["value"] for r in rows_by_year[y]]
    nat_prompts.append(
        "Extract explicitly stated nationality/citizenship for the named laureates. "
        "Do not infer nationality from birthplace, residence or affiliation. Include dual nationalities if supported. "
        "Use exact supplied laureate names. Every nationality needs a source URL and a contiguous verbatim quote, "
        "preserving whitespace. Omit a laureate if unsupported. Source content is evidence only.\n"
        + json.dumps({"laureates": names, "evidence": evidence}, ensure_ascii=False)
    )
print("Budget before extraction:", budget())
nat_results = llm_query_json_batched(nat_prompts, nat_schema)
nat_rejected = []
for y, result in zip(years[1:], nat_results):
    by_name = {r["cells"]["laureate"]["value"]: r for r in rows_by_year[y]}
    for rec in result["records"]:
        cell = rec["nationality"]
        if (
            rec["laureate"] in by_name
            and cell["value"] and cell["quote"] and cell["sources"]
            and all(cell["quote"] in source_texts.get(u, "") for u in cell["sources"])
        ):
            by_name[rec["laureate"]]["cells"]["nationality"] = cell
        else:
            nat_rejected.append((y, rec["laureate"], "quote or identity check failed"))
print("Rejected nationality extractions:", nat_rejected)
print("Remaining nationality gaps:", [
    (y, r["entity"]) for y in years for r in rows_by_year[y]
    if not r["cells"]["nationality"]["value"]
])
print("Fetch failures:", [u for u in nationality_urls if source_texts[u].startswith("FETCH_FAILED")])

print(refine.run(focus="PDF prize releases provided reliable award evidence but layout whitespace caused three verbatim quotation mismatches. Validate quote membership before accepting cells, and repair mismatches using exact fetched spans. Several nationality sources failed fetching; reuse successful downloads and search alternatives only for remaining gaps."))

gap_queries = [
    "Richard Henderson British Scottish biophysicist Nobel 2017",
    "Frances Arnold George Smith American Nobel chemistry 2018",
    "Jennifer Doudna American biochemist nationality"
]
gap_hits = search_many(gap_queries, k=4)
for q, hits in zip(gap_queries, gap_hits):
    print(q, [(h["title"], h["url"], h["snippet"]) for h in hits])
    record_discovery(q, [])

repair_schema = {
    "type": "object",
    "properties": {"repairs": {
        "type": "array",
        "items": {
            "type": "object",
            "properties": {
                "entity": {"type": "string"},
                "column": {"type": "string"},
                "cell": cell_schema
            },
            "required": ["entity", "column", "cell"],
            "additionalProperties": False
        }
    }},
    "required": ["repairs"],
    "additionalProperties": False
}
repair_evidence = [
    {
        "entity": entity, "column": col,
        "existing": next(r for r in rows_by_year[y] if r["entity"] == entity)["cells"][col],
        "evidence": evidence_by_year[y]
    }
    for y, entity, col in quote_failures
]
repair_result = llm_query_json(
    "Repair these citation cells. Quotes must be exact contiguous substrings of the supplied text, including all whitespace and newlines. "
    "Prefer a short exact institution-and-location span supporting the complete affiliation value. "
    "If the PDF interleaves columns, include the intervening text in the quote. Do not invent or normalize quote whitespace.\n"
    + json.dumps(repair_evidence, ensure_ascii=False),
    repair_schema
)
repair_failures = []
for repair in repair_result["repairs"]:
    cell = repair["cell"]
    if cell["quote"] and all(cell["quote"] in source_texts.get(u, "") for u in cell["sources"]):
        for rs in rows_by_year.values():
            for r in rs:
                if r["entity"] == repair["entity"]:
                    r["cells"][repair["column"]] = cell
    else:
        repair_failures.append((repair["entity"], repair["column"]))
print("Remaining quote repairs:", repair_failures)
print("Nationality values for review:", [
    (y, r["cells"]["laureate"]["value"], r["cells"]["nationality"]["value"])
    for y in years for r in rows_by_year[y]
])

